    let mut out = Vec::new();
    for &value in values {
        let mut groups = [0u8; 5];
        let mut v = value;
        let mut i = 0;
        while v > 0 {
            groups[i] = (v & 0x7f) as u8;
            v >>= 7;
            i += 1;
